def is_palindrome(s):
    return s == s[::-1]

# Read the input string from the standard input
s = input().strip()

# Get the length of the input string
n = len(s)

# If the input string is not a palindrome
if not is_palindrome(s):
    # If the string is not a palindrome and its reverse with alternate characters removed is same as the original string
    # and the length of the string is more than 2, then print the length of the string minus 2
    if s == s[::-2] and n > 2:
        print(n - 2)
    # Otherwise, print the length of the string
    else:
        print(n)
else:
    # If all characters in the string are the same, print 0
    if all(c == s[0] for c in s):
        print(0)
    # Otherwise, print the length of the string minus 1
    else:
        print(n - 1)

